+++ b/src/service.ts
@@ -1,8 +1,26 @@
-import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const ZONE_NAME_RE = /^[A-Za-z_]+(?:\/[A-Za-z0-9_+\-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
-}
+  if (!ZONE_NAME_RE.test(name)) throw new RangeError(`invalid zone name: ${name}`);
+  let response: Response;
+  try {
+    response = await fetch(`${ZONES_URL}/${name}`);
+  } catch (e) {
+    throw new ZoneError(`tz service unavailable: ${(e as Error).message}`);
+  }
+  if (!response.ok) {
+    throw new ZoneError(`tz service unavailable: ${response.status}`);
+  }
+  let body: unknown;
+  try {
+    body = await response.json();
+  } catch {
+    throw new ZoneError("tz service: invalid JSON");
+  }
+  return parseZone(body);
+}
